const s = $json;
const now = new Date();
const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const monthNames = ['Januar','Februar','Maerz','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const monthLabel = monthNames[lastMonth.getMonth()] + ' ' + lastMonth.getFullYear();

const lines = [];
lines.push(`\ud83d\udcca Dein Monatsreport fuer ${monthLabel}:`);
lines.push('');
lines.push(`\ud83d\udcc5 ${s.termine_erstellt} Termin(e) angelegt`);
lines.push(`\ud83d\udccb ${s.notizen_aufgaben} Notiz(en)/Aufgabe(n) gemerkt, ${s.erledigte_aufgaben} davon erledigt`);
lines.push(`\ud83e\udd1d ${s.neue_leads} neue(r) Lead(s)`);
if (s.hubspot_aktionen > 0) lines.push(`\ud83d\udd17 ${s.hubspot_aktionen} HubSpot-Aktion(en)`);
lines.push(`\ud83d\udcac ${s.anfragen_gesamt} Anfragen insgesamt bearbeitet`);

const text = lines.join('\n');
return [{ json: { text } }];
